from typing import List

def contains_template(A: List[str], B: List[str]) -> str:
    N = len(A)
    M = len(B)

    def count_black_pixels(image: List[str]) -> int:
        return sum(row.count('#') for row in image)

    def shift_and_compare(A: List[str], B: List[str], dx: int, dy: int) -> bool:
        for i in range(M):
            for j in range(M):
                if A[i + dy][j + dx] != B[i][j]:
                    return False
        return True

    total_black_in_B = count_black_pixels(B)

    for i in range(N - M + 1):
        for j in range(N - M + 1):
            current_subimage = [A[x][j:j+M] for x in range(i, i+M)]
            total_black_in_current = count_black_pixels(current_subimage)
            if total_black_in_current == total_black_in_B and shift_and_compare(A, B, j, i):
                return "Yes"

    return "No"

